import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String inputStr = reader.readLine();
        int lengthMultiplier = 1;
        for (int i = 0; i < inputStr.length(); i++) {
            lengthMultiplier *= 10;
        }
        int count = 0;
        for (int num = 0; num < lengthMultiplier; num += 25) {
            if (matchesPattern(inputStr, num)) {
                count++;
            }
        }
        writer.println(count);
        writer.close();
    }

    public static boolean matchesPattern(String pattern, int number) {
        int digit = -1;
        for (int i = pattern.length() - 1; i >= 0; i--) {
            int currentDigit = number % 10;
            char c = pattern.charAt(i);
            if (c == 'X') {
                if (digit >= 0 && digit != currentDigit) {
                    return false;
                }
                digit = currentDigit;
            } else if (c != '_') {
                if (c - '0' != currentDigit) {
                    return false;
                }
            }
            if (pattern.length() > 1 && i == 0 && currentDigit == 0) {
                return false;
            }
            number /= 10;
        }
        return true;
    }
}
