#include <iostream>
#include <string>

int matchesPattern(const std::string& pattern, int number) {
    int digit = -1;
    for (int i = pattern.length() - 1; i >= 0; i--) {
        int currentDigit = number % 10;
        char c = pattern[i];
        if (c == 'X') {
            if (digit >= 0 && digit != currentDigit) {
                return false;
            }
            digit = currentDigit;
        } else if (c != '_') {
            if ((c - '0') != currentDigit) {
                return false;
            }
        }
        if (pattern.length() > 1 && i == 0 && currentDigit == 0) {
            return false;
        }
        number /= 10;
    }
    return true;
}

int main() {
    std::string inputStr;
    std::getline(std::cin, inputStr);
    int lengthMultiplier = 1;
    for (size_t i = 0; i < inputStr.length(); i++) {
        lengthMultiplier *= 10;
    }
    int count = 0;
    for (int num = 0; num < lengthMultiplier; num += 25) {
        if (matchesPattern(inputStr, num)) {
            count++;
        }
    }
    std::cout << count << std::endl;
    return 0;
}
